import{_ as r,o as a,c as e,a2 as i}from"./chunks/framework.YT-FC_Xx.js";const c=JSON.parse('{"title":"备份与恢复","description":"","frontmatter":{},"headers":[],"relativePath":"guide/backup.md","filePath":"guide/backup.md","lastUpdated":1792824910000}'),s={name:"guide/backup.md"};function o(d,t,l,n,h,u){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to &quot;备份与恢复&quot;">​</a></h1><p><strong>设置 → 备份与恢复</strong>：勾选数据类型导出为 JSON 文件，或从备份文件恢复所选类型。</p><h2 id="数据类型" tabindex="-1">数据类型 <a class="header-anchor" href="#数据类型" aria-label="Permalink to &quot;数据类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>包含</th></tr></thead><tbody><tr><td>用户</td><td>面板账号</td></tr><tr><td>服务器</td><td>服务器信息，包括单独设置的 <a href="./latency#给服务器单独设置">延迟测试点</a></td></tr><tr><td>隧道</td><td>隧道</td></tr><tr><td>规则</td><td>转发规则</td></tr><tr><td>用户隧道权限</td><td>用户能用哪些隧道</td></tr><tr><td>限速规则</td><td>限速</td></tr><tr><td>隧道分组 / 用户分组 / 分组权限</td><td>分组和按组授权</td></tr><tr><td>系统配置</td><td>设置页里的配置，包括延迟测试点</td></tr><tr><td>内核与入站</td><td>服务器上的内核、所有入站（包括导入的节点）、中转线路、流量统计基准，以及所有订阅（包括分享出去的）</td></tr></tbody></table><h2 id="恢复" tabindex="-1">恢复 <a class="header-anchor" href="#恢复" aria-label="Permalink to &quot;恢复&quot;">​</a></h2><ul><li>只恢复勾选的类型</li><li>恢复 <strong>内核与入站</strong> 后，面板会把内核配置重新推到在线的服务器，离线的服务器重连时自动补上</li><li>3.0.9 之前导出的备份不包含内核与入站，升级后请重新导出一次</li></ul><h2 id="上传到-github-gist" tabindex="-1">上传到 GitHub Gist <a class="header-anchor" href="#上传到-github-gist" aria-label="Permalink to &quot;上传到 GitHub Gist&quot;">​</a></h2><p>同一页下方的 <strong>上传到 GitHub Gist</strong> 可以把备份存到你自己的 GitHub 私密 Gist，每次上传是这个 Gist 的一个新版本，GitHub 会保留历史版本：</p><ul><li><strong>GitHub 令牌</strong>：在 GitHub → Settings → Developer settings → Personal access tokens 生成，只需要 <strong>gist</strong> 权限（Fine-grained 令牌选 Account permissions → Gists 读写）。保存时会先检查令牌能不能用，保存后不再显示；<strong>清除令牌</strong> 即停止上传</li><li><strong>加密密码（可选）</strong>：填了就先用它加密（scrypt + AES-256-GCM）再上传，恢复时要输入，忘记就无法恢复。留空则上传明文：私密 Gist 只是不公开列出，<strong>拿到链接的人能看到节点密码、订阅凭据等信息</strong></li><li><strong>自动上传</strong>：关闭 / 每 6 小时 / 每 12 小时 / 每天 / 每周。内容和上次一样时跳过，不产生新版本；失败时按 <a href="./notify">通知</a> 里勾选的「Gist 备份失败」提醒</li><li><strong>立即上传</strong>：第一次上传时自动新建私密 Gist；Gist 在 GitHub 上被删掉后，下次上传会新建一个</li><li><strong>从 Gist 恢复</strong>：选最近 10 个版本中的一个，加密的版本输入当时的密码，恢复全部数据类型（恢复前会先自动导出当前数据）。恢复用户后可能需要重新登录</li><li>令牌、密码和 Gist 设置不会写进备份，恢复备份也不会改动它们</li></ul><h2 id="不包含的内容" tabindex="-1">不包含的内容 <a class="header-anchor" href="#不包含的内容" aria-label="Permalink to &quot;不包含的内容&quot;">​</a></h2><ul><li>Telegram Bot Token 和 Webhook 地址</li><li><a href="./passkey">通行证密钥</a>：用 JSON 迁移后，用户需要用密码登录再重新绑定</li><li>延迟和监控的历史数据</li></ul><p>需要连同这些一起备份，直接备份数据库：SQLite 是部署目录里的数据文件（更新面板时安装脚本会自动备份到 <code>backups/</code>），PostgreSQL 见 <a href="./postgresql">PostgreSQL</a> 的“数据备份与恢复”。</p>',12)])])}const b=r(s,[["render",o]]);export{c as __pageData,b as default};
